create table if not exists public.studio_themes(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,business_id uuid references public.businesses(id) on delete cascade,name text not null check(char_length(name)<=80),description text not null default '' check(char_length(description)<=180),tokens jsonb not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());alter table public.studio_themes enable row level security;
create policy "studio themes personal read" on public.studio_themes for select using(business_id is null and owner_id=auth.uid());
create policy "studio themes personal write" on public.studio_themes for all using(business_id is null and owner_id=auth.uid()) with check(business_id is null and owner_id=auth.uid());
create policy "studio themes business read" on public.studio_themes for select using(business_id is not null and exists(select 1 from public.business_members bm where bm.business_id=studio_themes.business_id and bm.user_id=auth.uid() and bm.status='active'));
create policy "studio themes business write" on public.studio_themes for all using(business_id is not null and exists(select 1 from public.business_members bm where bm.business_id=studio_themes.business_id and bm.user_id=auth.uid() and bm.status='active')) with check(business_id is not null and exists(select 1 from public.business_members bm where bm.business_id=studio_themes.business_id and bm.user_id=auth.uid() and bm.status='active'));create index if not exists studio_themes_scope_idx on public.studio_themes(business_id,updated_at desc);notify pgrst,'reload schema';